do $$ declare s jsonb; d jsonb; begin select data into s from public.store_wallet_transactions where id='wtx_1793645427282_58' for update; select data into d from public.safe_transactions where id='st_1793645427282_velj' for update; if s?'voidedAt' and d?'voidedAt' then return; end if; if s->>'referenceNumber'<>'PRF-TR-427282' or d->>'referenceId'<>'PRF-TR-427282' or (s->>'amount')::numeric<>280.07 or (d->>'amount')::numeric<>280.07 or erp_private.profit_available('w_profits','')<>-280.07 then raise exception 'repair_precondition_changed'; end if; insert into erp_private.release_backup(table_name,rows) values('repair_profit_duplicate_PRF_TR_427282',jsonb_build_array(jsonb_build_object('table','store_wallet_transactions','id','wtx_1793645427282_58','data',s),jsonb_build_object('table','safe_transactions','id','st_1793645427282_velj','data',d))) on conflict(table_name) do nothing; update public.store_wallet_transactions set data=data||jsonb_build_object('amount',0,'voidedAt',now(),'voidedOriginalAmount',280.07,'voidedOriginalTransaction',s,'voidReason','Duplicate historical profit transfer from same exhausted balance; original retained in protected backup','description','ملغى: تحويل أرباح مكرر تاريخيًا PRF-TR-427282؛ الأصل محفوظ للمراجعة'),updated_at=now() where id='wtx_1793645427282_58'; update public.safe_transactions set data=data||jsonb_build_object('amount',0,'voidedAt',now(),'voidedOriginalAmount',280.07,'voidedOriginalTransaction',d,'voidReason','Paired credit of duplicate historical profit transfer','description','ملغى: وارد تحويل أرباح مكرر تاريخيًا PRF-TR-427282؛ الأصل محفوظ للمراجعة'),updated_at=now() where id='st_1793645427282_velj'; end $$; select erp_private.profit_available('w_profits','') as corrected_profit_available;
